import math

def prod_Square(n):
    if n < 4:
        return False
    m = math.isqrt(n)
    if m * m != n:
        return False
    # n = (i*j)^2 with i, j >= 2 requires the root m to be composite
    for d in range(2, math.isqrt(m) + 1):
        if m % d == 0:
            return True
    return False
