def max_sum_increasing_subseq(arr, n, i, k):
    # msis[j] = max sum of an increasing subsequence ending at index j (j <= i)
    msis = [arr[j] for j in range(n)]
    for a in range(1, i + 1):
        for b in range(a):
            if arr[a] > arr[b] and msis[b] + arr[a] > msis[a]:
                msis[a] = msis[b] + arr[a]

    # Append the kth element, which must be greater than the last chosen element
    best = arr[k]
    for j in range(i + 1):
        if arr[j] < arr[k]:
            best = max(best, msis[j] + arr[k])
    return best
